"use strict";

/**
 * Ailton Manager v2.0
 * Geração de PDF A4 real com pdf-lib carregada por CDN no index.html.
 * As imagens estão embutidas como data URI para funcionar tanto no GitHub Pages
 * quanto ao abrir o index.html localmente.
 */
(() => {
  const EMBEDDED_IMAGES = {"logo": "data:image/png;base64,", "watermark": "data:image/png;base64,", "qr": "data:image/png;base64,"};

  function ensurePdfLib() {
    if (!window.PDFLib) {
      throw new Error("O gerador de PDF não carregou. Verifique sua conexão com a internet e recarregue a página.");
    }
    return window.PDFLib;
  }

  function $(selector) { return document.querySelector(selector); }
  function value(id, fallback = "") { return $(id)?.value?.trim() || fallback; }
  function selectedShow() { return document.querySelector('input[name="showType"]:checked')?.value || "Resenha"; }
  function selectedIncluded() { return [...document.querySelectorAll('input[name="included"]:checked')].map((item) => item.value); }

  function numberFromMoney(raw) {
    const cleaned = String(raw || "").replace(/[^\d,.-]/g, "").replace(/\./g, "").replace(",", ".");
    const parsed = Number(cleaned);
    return Number.isFinite(parsed) ? parsed : 0;
  }

  function brl(number) {
    return Number(number || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
  }

  function dateLong(iso) {
    if (!iso) return "A definir";
    const date = new Date(`${iso}T12:00:00`);
    if (Number.isNaN(date.getTime())) return "A definir";
    return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "long", year: "numeric" }).format(date);
  }

  function slug(text) {
    return String(text || "cliente").normalize("NFD").replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-zA-Z0-9]+/g, "-").replace(/^-+|-+$/g, "").toLowerCase() || "cliente";
  }

  function collectData() {
    const total = numberFromMoney(value("#totalValue"));
    const deposit = numberFromMoney(value("#depositValue"));
    const balance = Math.max(total - deposit, 0);
    const showName = selectedShow();
    const showInfo = window.AILTON_SHOWS?.[showName] || {};
    const included = selectedIncluded();
    const includedSentence = included.length
      ? `Incluso nesta proposta: ${included.join(", ")}.`
      : "Serviços adicionais somente estarão incluídos quando expressamente descritos nesta proposta.";

    return {
      budgetNumber: value("#budgetNumber", "—"), clientName: value("#clientName", "Nome do cliente"),
      clientPhone: value("#clientPhone"), clientEmail: value("#clientEmail"),
      clientDocument: value("#clientDocument"), clientCity: value("#clientCity"), clientAddress: value("#clientAddress"),
      eventType: value("#eventType", "A definir"), eventDate: dateLong(value("#eventDate")),
      eventTime: value("#eventTime", "A definir"), eventVenue: value("#eventVenue"), eventCity: value("#eventCity"),
      showName, formation: showInfo.formation || "Formação musical", duration: value("#showDuration", showInfo.duration || "A definir"),
      description: showInfo.description || "Apresentação musical profissional.", total, deposit, balance,
      paymentMethod: value("#paymentMethod", "A combinar"), balanceDue: value("#balanceDue", "A combinar"),
      validity: value("#budgetValidity", "15 dias"), clientNotes: value("#clientNotes"), includedSentence,
    };
  }

  function dataUriBytes(uri) {
    const base64 = uri.split(",")[1];
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  function wrapText(text, font, size, maxWidth) {
    const paragraphs = String(text || "").split(/\n+/);
    const lines = [];
    for (const paragraph of paragraphs) {
      const words = paragraph.trim().split(/\s+/).filter(Boolean);
      if (!words.length) { lines.push(""); continue; }
      let current = words.shift();
      for (const word of words) {
        const test = `${current} ${word}`;
        if (font.widthOfTextAtSize(test, size) <= maxWidth) current = test;
        else { lines.push(current); current = word; }
      }
      lines.push(current);
    }
    return lines;
  }

  function drawWrapped(page, text, options) {
    const { x, y, font, size, color, maxWidth, lineHeight = size * 1.35, maxLines = 99 } = options;
    const lines = wrapText(text, font, size, maxWidth).slice(0, maxLines);
    lines.forEach((line, index) => page.drawText(line, { x, y: y - index * lineHeight, size, font, color }));
    return y - lines.length * lineHeight;
  }

  function label(page, text, x, y, font, color) {
    page.drawText(String(text).toUpperCase(), { x, y, size: 7, font, color, characterSpacing: 0.8 });
  }

  function infoBox(page, x, y, width, title, content, fonts, colors) {
    const height = 38;
    page.drawRectangle({ x, y: y - height, width, height, borderWidth: 0.6, borderColor: colors.line, color: colors.box });
    label(page, title, x + 9, y - 12, fonts.bold, colors.muted);
    const lines = wrapText(content || "A definir", fonts.bold, 8.2, width - 18).slice(0, 2);
    lines.forEach((line, index) => page.drawText(line, { x: x + 9, y: y - 26 - index * 10, size: 8.2, font: fonts.bold, color: colors.text }));
  }

  async function createPdfBlob() {
    const data = collectData();
    const { PDFDocument, StandardFonts, rgb } = ensurePdfLib();

    if (data.deposit > data.total) {
      throw new Error("O valor da entrada não pode ser maior que o valor total.");
    }

    const pdf = await PDFDocument.create();
    pdf.setTitle(`Proposta ${data.budgetNumber} - ${data.clientName}`);
    pdf.setAuthor("Ailton Souza");
    pdf.setSubject("Proposta Comercial - Apresentação Musical");
    pdf.setCreator("Ailton Manager");

    const page = pdf.addPage([595.28, 841.89]);
    const width = page.getWidth();
    const height = page.getHeight();

    const fonts = {
      regular: await pdf.embedFont(StandardFonts.Helvetica),
      bold: await pdf.embedFont(StandardFonts.HelveticaBold),
      serif: await pdf.embedFont(StandardFonts.TimesRomanBold),
    };

    const colors = {
      text: rgb(0.10, 0.10, 0.12),
      muted: rgb(0.43, 0.43, 0.45),
      gold: rgb(0.72, 0.56, 0.12),
      line: rgb(0.86, 0.86, 0.86),
      box: rgb(0.965, 0.958, 0.94),
      black: rgb(0.055, 0.055, 0.065),
      white: rgb(1, 1, 1),
      cream: rgb(0.985, 0.975, 0.93),
    };

    const logo = await pdf.embedPng(dataUriBytes(EMBEDDED_IMAGES.logo));
    const watermark = await pdf.embedPng(dataUriBytes(EMBEDDED_IMAGES.watermark));
    const qr = await pdf.embedPng(dataUriBytes(EMBEDDED_IMAGES.qr));

    const left = 56;
    const right = width - 56;
    const contentWidth = right - left;

    // Marca-d'água central, no mesmo espírito da versão impressa.
    const wmWidth = 285;
    const wmHeight = wmWidth * (watermark.height / watermark.width);
    page.drawImage(watermark, {
      x: (width - wmWidth) / 2,
      y: 270,
      width: wmWidth,
      height: wmHeight,
      opacity: 0.028,
    });

    // Cabeçalho compacto.
    const logoScale = Math.min(145 / logo.width, 46 / logo.height);
    page.drawImage(logo, {
      x: left,
      y: height - 82,
      width: logo.width * logoScale,
      height: logo.height * logoScale,
    });

    page.drawText("PROPOSTA COMERCIAL", {
      x: 218,
      y: height - 55,
      size: 10.5,
      font: fonts.bold,
      color: colors.text,
    });

    page.drawText("Apresentação Musical", {
      x: 218,
      y: height - 70,
      size: 8,
      font: fonts.regular,
      color: colors.muted,
    });

    label(page, "Orçamento", right - 68, height - 52, fonts.bold, colors.muted);
    page.drawText(data.budgetNumber, {
      x: right - fonts.bold.widthOfTextAtSize(data.budgetNumber, 10.5),
      y: height - 70,
      size: 10.5,
      font: fonts.bold,
      color: colors.text,
    });

    page.drawLine({
      start: { x: left, y: height - 96 },
      end: { x: right, y: height - 96 },
      thickness: 1,
      color: colors.gold,
    });

    let y = height - 121;

    label(page, "Apresentação musical", left, y, fonts.bold, colors.gold);
    y -= 24;

    page.drawText(data.showName, {
      x: left,
      y,
      size: 22,
      font: fonts.serif,
      color: colors.text,
    });

    y -= 17;
    page.drawText(`${data.formation} • Duração: ${data.duration}`, {
      x: left,
      y,
      size: 8.5,
      font: fonts.regular,
      color: colors.muted,
    });

    y -= 25;
    label(page, "Cliente", left, y, fonts.bold, colors.muted);
    y -= 15;

    page.drawText(data.clientName, {
      x: left,
      y,
      size: 11,
      font: fonts.bold,
      color: colors.text,
    });

    const contact = [data.clientPhone, data.clientEmail]
      .filter(Boolean)
      .join(" • ") || "Contato não informado";

    y -= 13;
    page.drawText(contact, {
      x: left,
      y,
      size: 7.7,
      font: fonts.regular,
      color: colors.muted,
    });

    y -= 21;
    const gap = 8;
    const boxWidth = (contentWidth - gap) / 2;

    infoBox(page, left, y, boxWidth, "Evento", data.eventType, fonts, colors);
    infoBox(page, left + boxWidth + gap, y, boxWidth, "Data", data.eventDate, fonts, colors);

    y -= 45;
    infoBox(page, left, y, boxWidth, "Horário", data.eventTime, fonts, colors);
    infoBox(
      page,
      left + boxWidth + gap,
      y,
      boxWidth,
      "Local",
      [data.eventVenue, data.eventCity].filter(Boolean).join(" — ") || "A definir",
      fonts,
      colors
    );

    y -= 54;
    label(page, "Descrição", left, y, fonts.bold, colors.muted);
    y -= 13;

    y = drawWrapped(page, data.description, {
      x: left,
      y,
      font: fonts.regular,
      size: 8.1,
      color: colors.text,
      maxWidth: contentWidth,
      lineHeight: 10.5,
      maxLines: 4,
    });

    y -= 10;

    // Investimento idêntico ao bloco escuro da versão impressa.
    const investHeight = 64;
    page.drawRectangle({
      x: left,
      y: y - investHeight,
      width: contentWidth,
      height: investHeight,
      color: colors.black,
    });

    page.drawText("Investimento", {
      x: left + 14,
      y: y - 18,
      size: 7.2,
      font: fonts.regular,
      color: rgb(0.78, 0.78, 0.78),
    });

    page.drawText(brl(data.total), {
      x: left + 14,
      y: y - 43,
      size: 22,
      font: fonts.serif,
      color: rgb(0.94, 0.84, 0.42),
    });

    page.drawText(`Forma de pagamento: ${data.paymentMethod}`, {
      x: left + 250,
      y: y - 25,
      size: 7.8,
      font: fonts.regular,
      color: colors.white,
    });

    page.drawText(`Saldo: ${data.balanceDue}`, {
      x: left + 250,
      y: y - 42,
      size: 7.8,
      font: fonts.regular,
      color: colors.white,
    });

    y -= investHeight + 8;

    infoBox(page, left, y, boxWidth, "Entrada", brl(data.deposit), fonts, colors);
    infoBox(page, left + boxWidth + gap, y, boxWidth, "Saldo", brl(data.balance), fonts, colors);

    y -= 51;
    label(page, "Condições da proposta", left, y, fonts.bold, colors.muted);
    y -= 13;

    const conditions = [
      data.clientNotes,
      data.includedSentence,
      `Validade da proposta: ${data.validity}.`,
      `Saldo: ${data.balanceDue}.`,
    ].filter(Boolean).join(" ");

    y = drawWrapped(page, conditions, {
      x: left,
      y,
      font: fonts.regular,
      size: 7.45,
      color: colors.text,
      maxWidth: contentWidth,
      lineHeight: 9.6,
      maxLines: 7,
    });

    y -= 8;

    const closing =
      "Agradecemos pela oportunidade de apresentar esta proposta. Será uma satisfação fazer parte do seu evento, proporcionando uma apresentação musical de qualidade, profissionalismo e uma experiência memorável para você e seus convidados.";

    const closingHeight = 48;
    page.drawRectangle({
      x: left,
      y: y - closingHeight,
      width: contentWidth,
      height: closingHeight,
      color: colors.cream,
    });

    page.drawRectangle({
      x: left,
      y: y - closingHeight,
      width: 3,
      height: closingHeight,
      color: colors.gold,
    });

    drawWrapped(page, closing, {
      x: left + 11,
      y: y - 13,
      font: fonts.regular,
      size: 7.15,
      color: colors.muted,
      maxWidth: contentWidth - 22,
      lineHeight: 9,
      maxLines: 4,
    });

    y -= closingHeight + 9;

    // Rodapé logo abaixo do agradecimento, sem o vazio excessivo da versão anterior.
    page.drawLine({
      start: { x: left, y: y },
      end: { x: right, y },
      thickness: 0.8,
      color: colors.line,
    });

    y -= 16;

    page.drawText("Ailton Souza", {
      x: left,
      y,
      size: 10,
      font: fonts.bold,
      color: colors.text,
    });

    page.drawText("Cantor • Eventos • Shows • Casamentos", {
      x: left,
      y: y - 13,
      size: 6.9,
      font: fonts.regular,
      color: colors.muted,
    });

    page.drawText("(61) 99584-0847 • cantorailtonsouza@gmail.com", {
      x: left,
      y: y - 26,
      size: 6.9,
      font: fonts.regular,
      color: colors.muted,
    });

    page.drawText("www.ailtonsouza.com.br", {
      x: left,
      y: y - 39,
      size: 6.9,
      font: fonts.regular,
      color: colors.muted,
    });

    const qrSize = 55;
    page.drawImage(qr, {
      x: right - qrSize - 48,
      y: y - 49,
      width: qrSize,
      height: qrSize,
    });

    page.drawText("Acesse o site", {
      x: right - 43,
      y: y - 27,
      size: 6.4,
      font: fonts.regular,
      color: colors.muted,
    });

    const bytes = await pdf.save();
    const blob = new Blob([bytes], { type: "application/pdf" });
    const filename = `orcamento-${data.budgetNumber.replace("/", "-")}-${slug(data.clientName)}.pdf`;
    return { blob, filename, data };
  }

  function downloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url; link.download = filename; document.body.appendChild(link); link.click(); link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
  }

  async function shareOrDownload() {
    const result = await createPdfBlob();
    const file = new File([result.blob], result.filename, { type: "application/pdf" });
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file], title: `Proposta ${result.data.budgetNumber} - Ailton Souza`,
        text: `Olá, ${result.data.clientName}! Segue a proposta comercial para seu evento.` });
      return "shared";
    }
    downloadBlob(result.blob, result.filename);
    return "downloaded";
  }

  async function download() { const result = await createPdfBlob(); downloadBlob(result.blob, result.filename); }
  window.AiltonPdf = { createPdfBlob, shareOrDownload, download };
})();
